using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable]public sealed class AdQuoteCase{public string kind,job,skipJob;public int index,remaining;public NumberData amount;public long day,cost;public double cooldown,seconds;public bool allowed,skipAllowed;}
 [Serializable]public sealed class AdStep{public string action,kind,tx,result,job,capsuleDay;public int index;public long cost;public double at,componentsEarned,regularCredits,completed;public AdState ads;public CommerceState commerce;public RetentionState retention;public string[] transactions,queue,adTransactions;public long[] components;public int[] research;public bool hasResearchJob;public Job researchJob;public Job[] labs;public int capsuleVideos;public NumberData credits,eligible,income;public AdQuoteCase[] quotes;}
 [Serializable]public sealed class AdScenario{public string name;public StateData before;public AdStep[] steps;}
 [Serializable]public sealed class AdCases{public int transactions;public AdScenario[] scenarios;}
 public sealed class AdTests
 {
  static void Near(ScientificNumber actual,NumberData expected,string label){var e=ScientificNumber.FromData(expected);Assert.That(actual.IsZero,Is.EqualTo(e.IsZero),label);if(!e.IsZero)Assert.That(actual.Log10(),Is.EqualTo(e.Log10()).Within(2e-10),label);}
  static void Job(Job a,Job b,string label){Assert.That(a==null,Is.EqualTo(b==null),label);if(a==null)return;Assert.That(a.id,Is.EqualTo(b.id),label);Assert.That(a.key,Is.EqualTo(b.key),label+" identity");Assert.That(a.slot,Is.EqualTo(b.slot),label+" slot");Assert.That(a.required,Is.EqualTo(b.required).Within(Math.Max(1e-6,b.required*1e-12)),label);Assert.That(a.done,Is.EqualTo(b.done).Within(Math.Max(1e-6,b.required*1e-12)),label);}
  [Test]public void RewardTicketsResearchSkipsAndLegacyEffectsMatchActualSource()
  {var f=JsonUtility.FromJson<AdCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/AdReferenceCases.json")));int count=0;foreach(var scenario in f.scenarios){var s=scenario.before.ToState();foreach(var c in scenario.steps){string label=scenario.name+" / "+count++ +" "+c.action+" "+c.kind,original=JsonUtility.ToJson(StateData.From(s));var n=s;switch(c.action){case "begin":n=AdRewards.Begin(s,c.kind,c.tx,c.index);break;case "complete":n=AdRewards.Complete(s,c.tx,c.result);break;case "cancel":n=AdRewards.Cancel(s,c.tx);break;case "research":n=Game.Research(s,c.kind);break;case "queue":n=PrestigeAutomation.QueueResearch(s,c.kind);break;case "skip":n=AdRewards.BuySkip(s,c.index,c.job,c.cost);break;case "clock":n=s.Copy();n.SavedAt=c.at;break;case "advance":n=Game.Advance(s,c.at);break;case "context":n=s.Copy();n.Prestige.resets++;break;case "capacity":n=s.Copy();n.Workshop.nodes=Array.Empty<string>();break;case "legacy":n=AdRewards.Legacy(s,c.kind,c.tx,c.result,c.at);break;}Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),label+" pure");var actual=n.Ads.Copy();var expected=c.ads.Copy();if(actual.hasPending&&expected.hasPending){Near(ScientificNumber.FromData(actual.pending.amount),expected.pending.amount,label+" frozen amount");actual.pending.amount=expected.pending.amount=null;}Assert.That(JsonUtility.ToJson(actual),Is.EqualTo(JsonUtility.ToJson(expected)),label+" limits/cooldowns/pending");Assert.That(JsonUtility.ToJson(n.Commerce),Is.EqualTo(JsonUtility.ToJson(c.commerce)),label+" receipt");Assert.That(JsonUtility.ToJson(n.Retention),Is.EqualTo(JsonUtility.ToJson(c.retention)),label+" Gems/ledger");Assert.That(n.Rewards.transactions,Is.EqualTo(c.transactions),label+" dedup");Assert.That(n.Workshop.components,Is.EqualTo(c.components),label+" components");Assert.That(n.Lifetime.componentsEarned,Is.EqualTo(c.componentsEarned),label+" producer");Assert.That(n.Lifetime.regularCredits,Is.EqualTo(c.regularCredits).Within(Math.Max(1e-6,Math.Abs(c.regularCredits)*1e-12)),label+" regular income");Assert.That(n.Research,Is.EqualTo(c.research),label+" real completion");Job(n.ResearchJob,c.hasResearchJob?c.researchJob:null,label);Assert.That(n.Prestige.labs.Length,Is.EqualTo(c.labs.Length),label);for(int i=0;i<c.labs.Length;i++)Job(n.Prestige.labs[i],c.labs[i],label);Assert.That(n.Prestige.researchQueue,Is.EqualTo(c.queue),label+" next queue");Assert.That(n.Lifetime.researchCompleted,Is.EqualTo(c.completed),label+" completions");Assert.That(n.Capsules.day,Is.EqualTo(c.capsuleDay),label);Assert.That(n.Capsules.videos,Is.EqualTo(c.capsuleVideos),label);Assert.That(n.Capsules.videoTransactions,Is.EqualTo(c.adTransactions),label);Near(n.Credits,c.credits,label+" credits");Near(n.Prestige.Eligible,c.eligible,label+" ineligible ad income");Near(Game.Income(n),c.income,label+" actual boost");foreach(var q in c.quotes){var a=AdRewards.Quote(n,q.kind,q.index);Near(a.Amount,q.amount,label+" quote amount");Assert.That(a.Day,Is.EqualTo(q.day),label);Assert.That(a.Remaining,Is.EqualTo(q.remaining),label);Assert.That(a.Cooldown,Is.EqualTo(q.cooldown),label);Assert.That(a.Job,Is.EqualTo(q.job),label);Assert.That(a.Allowed,Is.EqualTo(q.allowed),label);var skip=AdRewards.SkipQuote(n,q.index);Assert.That(skip.Job,Is.EqualTo(q.skipJob),label);Assert.That(skip.Seconds,Is.EqualTo(q.seconds).Within(1e-6),label);Assert.That(skip.Cost,Is.EqualTo(q.cost),label+" cost");Assert.That(skip.Allowed,Is.EqualTo(q.skipAllowed),label);}Game.Validate(n);s=n;}}Assert.That(count,Is.EqualTo(f.transactions));}
 }
}
